params.ts_type:
({
  id: string;
  name: string;
  baseUrl: string;
  protocol: "responses" | "chatCompletions" | "anthropicMessages";
  official: boolean;
  models: string[];
  keyCount: number;
  /** 后端旧版没有这两个字段（直连模式里挑出来的供应商列表）。 */
  enabled?: boolean;
  source?: string;
  /** 每百万 token 的价格。 */
  price?: { currency: string; input: number; cachedInput: number; output: number } | null;
  /** 按模型的价格（上游模型名 → 价格）；没填的模型用 `price`。 */
  modelPrices?: Record<string, { currency: string; input: number; cachedInput: number; output: number }>;
  /** 能画图的模型（不进聊天模型列表）；ChatGPT 账号是内置的一项。旧版后端没有。 */
  imageModels?: string[];
  /** 按模型的模型资料（思考等级等）JSON，格式同直连模式的「模型配置」。 */
  modelMetadata?: string;
  /** 按模型的上下文窗口（上游模型名 → token）；没写的模型用 `contextWindow`。 */
  modelWindows?: Record<string, number>;
  /** 没单独写窗口的模型用的窗口；都没有就用模型自带资料。 */
  contextWindow?: number | null;
  /** 自动压缩阈值（#3100）：窗口的百分比，按模型 + 默认值；没设时为空，用 Codex 默认。旧版后端没有。 */
  autoCompact?: { models?: Record<string, number>; fallback?: number | null } | null;
  /** 网关供应商单独走的 HTTP 代理，空串表示不单独走代理。 */
  proxy?: string;
  /** 主动限速：每个 Key 每分钟最多请求数；没有或 null 表示不限。旧版后端没有。 */
  keyRpm?: number | null;
  /** 主动限速：每个 Key 同时进行的最多请求数；没有或 null 表示不限。旧版后端没有。 */
  keyConcurrency?: number | null;
  /** 转发前移除托管生图工具（image_generation，#228）。旧版后端没有。 */
  stripImageGenerationTool?: boolean;
  /** 转发前移除 Responses 图片 `detail`（#2870）。旧版后端没有。 */
  stripResponsesImageDetail?: boolean;
  /** 不向该上游发送 `tool_search`（#2868）。旧版后端没有。 */
  disableToolSearch?: boolean;
  /** 登录得到的账号：chatgpt / copilot / grok；普通供应商为空。 */
  account?: string;
  subscriptionPolicy?: (Partial<Omit<({
  defaultUsedPercentLimit?: number | null;
  windowUsedPercentLimits: Record<string, number>;
  onLimit: "stop" | "nextPermitted" | "apiFallback";
  unknownUsage: "block" | "allow";
  maxAgeSeconds: number;
}), "windowUsedPercentLimits">> & {
  windowUsedPercentLimits?: Record<string, number> | null;
}) | null;
  /** 后端合并同账号所有别名策略后的准入结果。 */
  subscriptionBlockReason?: string | null;
  /** 订阅账号的套餐，如「ChatGPT Pro」「Copilot Pro+」。 */
  plan?: string;
  /** 后台检查时上游有、列表里没有的模型。 */
  upstreamNew?: string[];
  /** 后台检查时列表里有、上游已经没有的模型。 */
  upstreamGone?: string[];
  /** 这个 ChatGPT 账号正借给 Codex 登录。 */
  lentToCodex?: boolean;
  /** 订阅账号（或 OpenCode Go、Command Code 等套餐）的剩余额度；查不到或普通供应商为空。 */
  quota?: ({
  windows: ({ windowMinutes: number | null; usedPercent: number; resetsAtMs: number | null; observedAtMs?: number | null })[];
  updatedAtMs: number;
  windowsComplete?: boolean;
  officialAllowed?: boolean | null;
  officialLimitReached?: boolean | null;
  creditsAvailable?: boolean | null;
}) | null;
  /** 有额度可查（订阅账号，或按地址认出的 API Key 套餐，#3084）。旧版后端没有。 */
  quotaApi?: boolean;
  /** 已保存的 Key（打码，#2782）：订阅账号等不用 Key 的为空。旧版后端没有。 */
  keys?: { id: string; masked: string }[];
  /** 有余额接口的厂商（DeepSeek、Kimi 等，#2793）：卡片用「用量」页同一份余额。旧版后端没有。 */
  balanceApi?: boolean;
  /** new-api 访问令牌（打码，#2793）：只用来查账户余额；没配置为空。令牌原文不出后端。 */
  newapiAccess?: { masked: string; userId: string } | null;
  /** 自定义请求头（#3075）：敏感头只有打码后的 `masked`；订阅账号等不开放编辑的为空。旧版后端没有。 */
  customHeaders?: ({ key: string; value: string; masked?: string | null })[];
})
